A sequence of elements $(g_1,\ldots, g_r)$ in $G$ is called an \textbf{ordered basis} of $(G,\omega)$ if the continuous function
\begin{align*}
\mathbb{Z}_p^r&\to G\\
(x_1,\ldots, x_r)&\mapsto g_1^{x_1}\cdots g_r^{x_r}
\end{align*}
is a bijection (and hence a homeomorphism by the compactness of $\mathbb{Z}_p^r$), and satisfies the condition for all $x_i\in \mathbb{Z}_p$ that
$$\omega(g_1^{x_1}\cdots g_r^{x_r})=\min_i\{\omega(g_i)+v(x_i)\}$$
where $v$ is the valuation on $\mathbb{Z}_p$ normalized so that $v(p)=1$.

\label{gen_invariants}
We briefly note that the above proof immediately generalizes to showing that if $\Theta\subseteq \mathrm{End}(G)$ is any set of group homomorphisms $G\to G$, then $\omega|_{G^\Theta}$ is a saturated $p$-valuation on 
$$G^\Theta=\{g\in G\,|\,\theta(g)=g \text{ for all }\theta\in \Theta\}.$$

\label{Chev-Stein-isoms}
(See \cite[p. 97]{KP}.)  Our Chevalley-Steinberg system gives similar isomorphisms $u_{\tilde\alpha}:K_{\tilde\alpha}\xrightarrow{\sim}U_{\tilde\alpha}(K_{\tilde\alpha})$ from the $K_{\tilde\alpha}$-group isomorphisms $\mathbb{G}_a\xrightarrow{\sim} U_{\tilde\alpha}$.  We have the following concrete descriptions of how these two collections of isomorphisms interact.
\begin{itemize}
\item If $\alpha$ is of type R1, fix $\tilde\alpha\in \tilde\Phi$ lying above $\alpha$, so now the finite set $\{\sigma\tilde\alpha\,|\, \sigma\in \Theta/\Theta_{\tilde\alpha}\}$ is exactly the roots lying above $\alpha$.  Then for $x\in K_{\tilde\alpha}$,
$$u_\alpha(x)=\prod_{\sigma\in \Theta/\Theta_{\tilde\alpha}} u_{\sigma\tilde\alpha}(\sigma(x)).$$
Moreover, these terms commute (in fact, $U_\alpha$ is commutative).
\item If $\alpha$ is of type R2, or equivalently $2\alpha\in \Phi$ is of type R3, we fix $\tilde\alpha$ lying above $\alpha$, which determines a unique other root $\tilde\alpha'$ also lying above $\alpha$ which is not orthogonal to $\tilde\alpha$.  Now $\tilde\beta\coloneqq \tilde\alpha+\tilde\alpha'\in \tilde\Phi$ lies above $2\alpha$.  The preimages of $\alpha$ and $2\alpha$ in $\tilde\Phi$ are respectively
$$\{\sigma\tilde\alpha, \sigma\tilde\alpha'\,|\, \sigma\in \Theta/\Theta_{\tilde\beta}\},\qquad\{\sigma\tilde\beta\,|\, \sigma\in \Theta/\Theta_{\tilde\beta}\}.$$
As usual, let $\overline{(\cdot)}$ denote the nontrivial automorphism in $\mathrm{Gal}(K_{\tilde\alpha}/K_{\tilde\beta})$, which switches $\tilde\alpha$ and $\tilde\alpha'$.  Then for $(x,y)\in U_{K_{\tilde\alpha}/K_{\tilde\beta}}(K_{\tilde\beta})$,
\begin{align*}
u_\alpha(x,y)&=\prod_{\sigma\in \Theta/\Theta_{\tilde\beta}} \sigma\left(u_{\tilde\alpha}(x)u_{\tilde\alpha'}(\overline x)u_{\tilde\beta}(y)\right)\\
&=\prod_{\sigma\in \Theta/\Theta_{\tilde\beta}} u_{\sigma\tilde\alpha}(\sigma(x))u_{\sigma\tilde\alpha'}(\sigma(\overline x))u_{\sigma\tilde\beta}(\sigma(y)).
\end{align*}
Here, these three-term pieces indexed by $\sigma\in \Theta/\Theta_{\tilde\beta}$ commute with one another.  (We also note that we are abusing notation slightly in the final line, as strictly speaking $\sigma(x)$ for $x\in K_{\tilde\alpha}$ is not well-defined for $\sigma\in \Theta/\Theta_{\tilde\beta}$, however the three-term piece as a whole is fixed under the action of $\Theta_{\tilde\beta}$, so one could merely fix a set of representatives of $\Theta/\Theta_{\tilde\beta}$ and the result is independent of this choice.)
\end{itemize}

\label{R2-desc}
Under the isomorphism between $U_\alpha(F)$ and our original root group of type R2 in $G(K)$ (in the case when $F=K_{\tilde\beta}$) arising from our Chevalley-Steinberg system, the subgroup of $U_\alpha(F)$ corresponding to $U_{\alpha,x,\frac1{p-1}+}$ will be denoted in this subsection by $U_{\alpha}^a$, and can be described by
\begin{align*}
U_{\alpha}^a&=\left\{u_\alpha(x,y)\in U_\alpha(F)\,\Bigg|\, v(x)>\frac1{p-1}-a,\quad v(y)>\frac1{p-1}-2a\right\}\\
&=\left\{u_\alpha(x,y)\in U_\alpha(F)\,\bigg|\, x\in \mathfrak m_E^i, y\in \mathfrak m_E^j\right\},
\end{align*}
where $i$ is the least integer strictly greater than $e_F\cdot \left(\frac1{p-1}-a\right)$ and $j$ is the least integer strictly greater than $e_F\cdot \left(\frac1{p-1}-2a\right)$.  (We remark that $2i\geq j$, so $U_{\alpha}^a$ is easily seen to indeed be a subgroup.  This description follows from \cite[Definition 7.3.3]{KP} and \cite[Lemma 6.1.6]{KP}.)  We also note for future reference that, in fact, this same description applies to $U_{\alpha,x,r+}$ for any $r\geq 0$; one simply replaces $\frac1{p-1}$ by $r$ wherever it appears.

The function $\omega$ in Proposition \ref{root-group-pval} corresponds to the function on $U_{\alpha}^a$ defined by
$$\omega(u_\alpha(x,y))=\min\{v(x)+a,v(y)+2a\}.$$
We claim that it is a $p$-valuation, and will show later in this subsection that it is saturated.

\label{compatibility}
Using Remark \ref{tracelessexistence}, fix a traceless element $\gamma\in \mathcal O_E$ such that $\{1,\gamma\}$ is an $\mathcal O_F$-basis of $\mathcal O_E$.  Consider the following closed subgroups of $U_\alpha^a$:
\begin{align*}
U_{\alpha,1}^a&\coloneqq\left\{u_\alpha\left(x,\frac12x^2\right)\,\Bigg|\, x\in F, \quad v(x)>\frac1{p-1}-a\right\},\\ U_{\alpha,2}^a&\coloneqq \left\{u_\alpha\left(y\gamma,-\frac12y^2\gamma^2\right)\,\Bigg|\, y\in F, \quad v(y)>\frac1{p-1}-a-v(\gamma)\right\},\\
U_{\alpha,3}^a&\coloneqq \left\{u_\alpha(0,z\gamma)\,\Bigg|\, z\in F, \quad v(z)>\frac1{p-1}-2a-v(\gamma)\right\}.
\end{align*}
The multiplication map $U_{\alpha,1}^a\times U_{\alpha,2}^a\times U_{\alpha,3}^a\to U_\alpha^a$ is bijective, and the $p$-valuation $\omega$ on $U_\alpha^a$ is compatible with $(U_{\alpha,1}^a,U_{\alpha,2}^a,U_{\alpha,3}^a)$.

\label{basis}
Let $(b_1,\ldots, b_\ell)$ be an ordered basis for $\mathcal O_F$, and fix a traceless element $\gamma\in \mathcal O_E$ such that $\{1,\gamma\}$ is an $\mathcal O_F$-basis for $\mathcal O_E$.  Fix any uniformizer $\varpi_F\in \mathcal O_F$.  Then the following is an ordered basis for $U_\alpha^a$:
\begin{align}
g_{1,i}&\coloneqq u_\alpha\left(\varpi_F^{n_1}b_i, \frac12\varpi_F^{2n_1}b_i^2\right),\notag\\
g_{2,i}&\coloneqq u_\alpha\left(\varpi_F^{n_2}b_i\gamma, -\frac12\varpi_F^{2n_2}b_i^2\gamma^2\right),\tag{$i\leq \ell$}\\
g_{3,i}&\coloneqq u_\alpha(0,\varpi_F^{n_3}b_i\gamma).\notag
\end{align}

\label{general-existence}
For each $x\in \mathcal B(G)$, the filtration on $G_{x,\frac1{p-1}+}$ defined by
\begin{equation}\label{pval-def}\omega_x(g)\coloneqq \sup\{r>0\,|\, g\in G_{x,r}\}\end{equation}
is a saturated $p$-valuation.  Moreover, this is compatible with the Iwahori decomposition \ref{IwaDecomp}.

By a result of Steinberg in \cite{Steinberg}, there is a finite unramified (hence Galois) extension $L/K$ such that $G_L$ is a quasisplit reductive $L$-group (this fact is also used in \cite[p. 218]{totaro}).  Let $\Theta=\mathrm{Gal}(L/K)$.  By \cite[Proposition 9.8.3]{KP}, we have for any $r>0$ that 
\begin{equation*}
G_{x,r}=(G_L)_{x,r}\cap G(K)=(G_L)_{x,r}^\Theta,
\end{equation*}
so $\omega_x:G_{x,\frac1{p-1}+}\setminus\{1\}\to \left(\frac1{p-1},\infty\right)$ is merely the restriction to $G_{x,\frac1{p-1}+}=(G_L)_{x,\frac1{p-1}+}^\Theta$ of the saturated $p$-valuation $\omega_x:(G_L)_{x,\frac1{p-1}+}\setminus\{1\}\to \left(\frac1{p-1},\infty\right)$.  Thus, by Remark \ref{gen_invariants}, we find that $\omega_x$ is a saturated $p$-valuation on $G_{x,\frac1{p-1}+}$.  It is now immediate from the definition \ref{pval-def} that $\omega_x$ is compatible with the Iwahori decomposition \ref{IwaDecomp}.

\label{explicit-iso}
The map $\Phi_G$ is an isomorphism of Lie $K$-algebras, providing us with a concrete isomorphism between the analytically and algebraically defined Lie $K$-algebras
$$\mathrm{Lie}(G(K))\cong \mathrm{Der}_e(G(K),K)\xrightarrow{\Phi_G} \mathrm{Der}_\epsilon(A,K)\cong \mathrm{Lie}(G)(K).$$

Following \cite[Section 8.5]{KP} (which still applies because $G$ is quasisplit despite $K$ having proper unramified extensions; see \cite[13.3.3]{KP}, for example), there exist smooth integral $\mathcal O_K$-models $\mathcal G_{x,r}$ and $\mathcal T_r$ of $G$ and $T$, as well as $\mathcal U_{\alpha,x,r}$ of $U_\alpha$ for $\alpha\in \Phi^{+,\mathrm{nd}}$ for all $r\geq 0$, satisfying the following:
$$G_{x,r}=\mathcal G_{x,r}(\mathcal O_K),\qquad T(K)_r=\mathcal T_r(\mathcal O_K),\qquad U_{\alpha, x, r}=\mathcal U_{\alpha, x, r}(\mathcal O_K).$$
Write $\mathfrak g_{x,r}=\mathrm{Lie}(\mathcal G_{x,r})(\mathcal O_K)$, $\mathfrak t_r=\mathrm{Lie}(\mathcal T_r)(\mathcal O_K)$, and $\mathfrak u_{\alpha, x, r}=\mathrm{Lie}(\mathcal U_{\alpha, x, r})(\mathcal O_K)$, all of which are $\mathcal O_K$-lattices in their respective ambient Lie $K$-algebras $\mathrm{Lie}(G)(K)$, $\mathrm{Lie}(T)(K)$, and $\mathrm{Lie}(U_\alpha)(K)$.  By \cite[8.5.20]{KP}, we have for any $r\geq 0$ a natural identification of $\mathcal O_K$-modules
\begin{equation}\label{OK-lattices}
\mathfrak g_{x,r}=\bigoplus_{\alpha\in \Phi^{-,\mathrm{nd}}} \mathfrak u_{\alpha, x, r}\oplus \mathfrak t_r \oplus\bigoplus_{\alpha\in \Phi^{+,\mathrm{nd}}} \mathfrak u_{\alpha, x, r}
\end{equation}
lying within
\begin{equation}\label{K-vs}
\mathrm{Lie}(G)(K)=\bigoplus_{\alpha\in \Phi^{-,\mathrm{nd}}} \mathrm{Lie}(U_\alpha)(K)\oplus \mathrm{Lie}(T)(K)\oplus\bigoplus_{\alpha\in \Phi^{+,\mathrm{nd}}}\mathrm{Lie}(U_\alpha).
\end{equation}

Recall by Proposition \ref{existence} that we have a saturated $p$-valuation $\omega\coloneqq\omega_x$ on $G_{x,\frac1{p-1}+}$ given by
$$\omega(g)=\sup\{r>0\,|\, g\in G_{x,r}\}.$$
Moreover, we have for each $r>\frac1{p-1}$ an Iwahori decomposition
$$\prod_{\alpha\in \Phi^{-,\mathrm{nd}}} U_{\alpha, x, r}\times T(K)_r\times \prod_{\alpha\in \Phi^{+,\mathrm{nd}}} U_{\alpha, x, r}\xrightarrow{\sim} G_{x,r}$$
and $\omega|_{G_{x,r}}$ is compatible with this decomposition for all $r>\frac1{p-1}$.  One can easily show using Remark \ref{compatible-saturation} and \cite[Proposition 31.2]{schneiderbook}, which gives us a way of creating explicit $\mathbb{Q}_p$-bases of all such Lie algebras, that there is a natural identification of $\mathbb{Q}_p$-vector spaces
\begin{equation}\label{Qp-vs-0}
L_\omega(G_{x,\frac1{p-1}+})=\bigoplus_{\alpha\in \Phi^{-,\mathrm{nd}}} L_\omega(U_{\alpha,x, \frac1{p-1}+})\oplus L_\omega(T(K)_{\frac1{p-1}+})\oplus\bigoplus_{\alpha\in \Phi^{+,\mathrm{nd}}} L_\omega(U_{\alpha, x, \frac1{p-1}+}).
\end{equation}
One can further use the explicit description of the filtrations $\tilde\omega$ on each of these Lie $\mathbb{Q}_p$-algebras from \cite[Proposition 31.2]{schneiderbook} to conclude that, within this decomposition, there is an identification of $\mathbb{Z}_p$-lattices
\begin{equation}\label{Zp-lattices}
L_\omega(G_{x,\frac1{p-1}+})_r=\bigoplus_{\alpha\in \Phi^{-,\mathrm{nd}}} L_\omega(U_{\alpha,x, \frac1{p-1}+})_r\oplus L_\omega(T(K)_{\frac1{p-1}+})_r\oplus\bigoplus_{\alpha\in \Phi^{+,\mathrm{nd}}} L_\omega(U_{\alpha, x, \frac1{p-1}+})_r
\end{equation}
for every $r>\frac1{p-1}$.  We note for future use that $L_\omega(G_{x,\frac1{p-1}+})_r=\log(G_{x,r})$ for all $r>\frac1{p-1}$ by \cite[p. 220]{schneiderbook}, and the same holds for each of the terms in our Iwahori decomposition \ref{Zp-lattices}.  We also remark that one can easily show that there is a natural identification of $\mathbb{Q}_p$-vector spaces
\begin{equation}\label{Qp-vs}
\mathrm{Lie}(G(K))=\bigoplus_{\alpha\in \Phi^{-,\mathrm{nd}}} \mathrm{Lie}(U_\alpha(K))\oplus\mathrm{Lie}(T(K))\oplus \bigoplus_{\alpha\in \Phi^{+,\mathrm{nd}}} \mathrm{Lie}(U_\alpha(K)).
\end{equation}

\label{LieAlg-cases}
Let $r>\frac1{p-1}$ be fixed.
\begin{enumerate}
\item \label{LieAlg-cases-torus} The images of $\log(T(K)_r)$ and $\mathfrak t_r$ under these two maps coincide.
\item \label{LieAlg-cases-root} For each $\alpha\in \Phi^{\mathrm{nd}}$, the images of $\log(U_{\alpha,x,r})$ and $\mathfrak u_{\alpha, x, r}$ under these two maps coincide.
\end{enumerate}

\label{qsplit-expl-desc}
Fix $r>\frac1{p-1}$ and fix a Chevalley-Steinberg system, from which there arises an absolutely special point $x_0\in \mathcal A(S)$, and we can write $x=x_0+v$ for $v\in V(S_\mathrm{ad})$ (as in Remark \ref{root-filts}).  To ease notation, write $\Theta=\mathrm{Gal}(\overline K/K)$.  Given $\alpha\in \Phi^\mathrm{nd}$, we can describe the isomorphism of Lie $\mathbb{Z}_p$-algebras
\begin{equation}\label{root-LieAlg}
\log(U_{\alpha, x, r})\xrightarrow{\sim} \mathfrak u_{\alpha, x, r}\end{equation}
by chasing through the proofs of Claims \ref{R1-LieAlg} and \ref{R2-LieAlg} as follows.
\begin{itemize}
\item If $\alpha$ is of type R1, then \ref{root-LieAlg} sends 
$$\log(u_\alpha(x))\mapsto \sum_{\sigma\in \Theta/\Theta_{\tilde\alpha}} \sigma(x\cdot X_{\tilde\alpha})$$
for $x\in K_{\tilde\alpha}$ with $v(x)\geq r-\langle \alpha,v\rangle$.
\item If $\alpha$ is of type R2, let $\gamma\in \mathcal O_{K_{\tilde\alpha}}$ be a traceless element such that $\{1,\gamma\}$ is an $\mathcal O_{K_{\tilde\beta}}$-basis of $\mathcal O_{K_{\tilde\alpha}}$, which exists by Remark \ref{tracelessexistence}.  Then \ref{root-LieAlg} sends
\begin{align*}
\log\left(u_\alpha\left(x,\frac12x^2\right)\right)&\mapsto \sum_{\sigma\in \Theta/\Theta_{\tilde\beta}} \sigma(x\cdot X_{\tilde\alpha}),\\
\log\left(u_\alpha\left(y\gamma,-\frac12y^2\gamma^2\right)\right)&\mapsto \sum_{\sigma\in \Theta/\Theta_{\tilde\beta}} \sigma(y\gamma\cdot X_{\tilde\alpha}),\\
\log\left(u_\alpha\left(0,z\gamma\right)\right)&\mapsto \sum_{\sigma\in \Theta/\Theta_{\tilde\beta}} \sigma(z\gamma\cdot X_{\tilde\beta}),
\end{align*}
where $x,y,z\in K_{\tilde\beta}$ satisfy
$$v(x)\geq r-\langle \alpha,v\rangle,\quad v(y)\geq r-\langle \alpha, v\rangle-v(\gamma),\quad v(z)\geq r-2\langle \alpha, v\rangle -v(\gamma).$$
\end{itemize}

As in the proof of Theorem \ref{general-existence}, let $L/K$ be a finite unramified (hence Galois) extension such that $G_L$ is a quasisplit reductive $L$-group.  Then Proposition \ref{qsplit-LieAlg-iso} provides us with compatible isomorphisms
\begin{equation}\label{basechange}
\log(G(L)_{x,r})\xrightarrow{\sim} \mathfrak g(L)_{x,r}
\end{equation}
of Lie $\mathbb{Z}_p$-algebras for any $r>\frac1{p-1}$.  Recall that, as an isomorphism of $\mathbb{Z}_p$-modules, this is a direct sum of isomorphisms defined on each Iwahori factor; moreover, we have concrete descriptions of these maps on the Iwahori factors given by Remarks \ref{cochars} and \ref{qsplit-expl-desc}.  One can immediately deduce from these descriptions that the map \ref{basechange} is in fact $\mathrm{Gal}(L/K)$-equivariant, from which we find an isomorphism of Lie $\mathbb{Z}_p$-algebras
$$\log\left(G(L)_{x,r}^{\mathrm{Gal}(L/K)}\right)\xrightarrow{\sim} \mathfrak g(L)_{x,r}^{\mathrm{Gal}(L/K)},$$
which can be rewritten as $\log(G_{x,r})\xrightarrow{\sim} \mathfrak g_{x,r}$.  Because these isomorphisms are compatible, it follows that we have an isomorphism $\log(G_{x,\frac1{p-1}+})\xrightarrow{\sim} \mathfrak g_{x,\frac1{p-1}+}$ which respects the filtrations.

\label{MP-cor}
The Moy-Prasad isomorphisms
$$\mathrm{MP}_{x,r,r+}: G_{x,r}/G_{x,r+}\xrightarrow{\sim} \mathfrak g_{x,r}/\mathfrak g_{x,r+}$$
for $r>\frac1{p-1}$ fit together to form an isomorphism of Lie $\mathbb{F}_p[\varepsilon]$-algebras
\begin{equation}\label{MP}\mathrm{MP}: \operatorname{gr} G_{x,\frac1{p-1}+}\xrightarrow{\sim} \operatorname{gr} \mathfrak g_{x,\frac1{p-1}+}.\end{equation}
